SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, PERCENT_RANK() OVER (PARTITION BY brand ORDER BY cost ASC NULLS FIRST) AS cost_percent_rank, LAG(stock_qty, 1) OVER w_ordered AS prev_stock_qty, AVG(price) OVER w_hist AS price_avg_5, LAST_VALUE(brand) IGNORE NULLS OVER (PARTITION BY brand ORDER BY stock_qty ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_brand, AVG(stock_qty) OVER (PARTITION BY supplier_id ORDER BY cost ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS stock_qty_avg_3 FROM products WINDOW w_ordered AS (PARTITION BY brand, supplier_id ORDER BY launch_date ASC, id ASC), w_hist AS (ORDER BY launch_date ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW)
